:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #253b3a;
  background: #f2eee5;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at top, #fffaf0, #f2eee5 65%);
}
.card {
  width: min(100%, 460px);
  padding: clamp(22px, 6vw, 36px);
  border: 1px solid #e3dccd;
  border-radius: 24px;
  background: #fffdf8;
  box-shadow: 0 18px 50px #51472b18;
}
header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #ad6553; font-size: .85rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.8rem, 8vw, 2.35rem); line-height: 1.1; letter-spacing: -.04em; }
.intro { max-width: 320px; margin: 14px auto 0; color: #64716d; line-height: 1.5; }
.status { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 24px 0 14px; }
.status p { margin: 0; }
.status strong { margin-left: 5px; font-size: 1.2rem; }
.message { color: #64716d; text-align: right; }
.grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 7px;
  padding: 10px;
  border-radius: 16px;
  background: #f2eee5;
}
.tile {
  aspect-ratio: 1;
  min-width: 0;
  border: 2px solid #fffdf8;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 120ms ease, filter 120ms ease;
}
.tile:hover { transform: scale(1.06); filter: brightness(1.04); }
.tile:active { transform: scale(.94); }
.tile:focus-visible, button:focus-visible { outline: 3px solid #253b3a; outline-offset: 3px; }
.coral { background: #e88772; }
.teal { background: #61aaa0; }
.gold { background: #efc45f; }
.palette { margin: 22px 0 0; padding: 0; border: 0; }
.palette legend { margin-bottom: 10px; font-weight: 700; }
.swatches { display: flex; gap: 12px; }
.swatch { width: 48px; height: 48px; border: 3px solid #fffdf8; border-radius: 50%; box-shadow: 0 0 0 1px #d9d2c4; cursor: pointer; transition: transform 120ms ease, box-shadow 120ms ease; }
.swatch:hover { transform: translateY(-2px); }
.swatch[aria-pressed="true"] { box-shadow: 0 0 0 3px #253b3a; }
.swatch:active, .restart:active { transform: scale(.96); }
.restart { width: 100%; margin-top: 20px; padding: 12px 16px; border: 1px solid #c9d4ce; border-radius: 12px; background: #edf3ee; color: #253b3a; font: inherit; font-weight: 700; cursor: pointer; transition: background 120ms ease, transform 120ms ease; }
.restart:hover { background: #e0ebe3; }
[hidden] { display: none !important; }
@media (max-width: 400px) {
  body { padding: 16px 12px; }
  .grid { gap: 5px; padding: 8px; }
  .tile { border-radius: 6px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; }
}

const startingPattern = [
  ['coral','coral','teal','teal','gold','gold'],
  ['coral','teal','teal','gold','gold','coral'],
  ['coral','coral','teal','gold','coral','coral'],
  ['teal','coral','gold','gold','teal','coral'],
  ['teal','teal','gold','coral','teal','teal'],
  ['gold','teal','coral','coral','teal','gold']
];
const grid = document.querySelector('#grid');
const moveCount = document.querySelector('#move-count');
const message = document.querySelector('#message');
const colorButtons = [...document.querySelectorAll('.swatch')];
let cells = [];
let moves = 0;
let selectedColor = null;
let finished = false;

function render() {
  grid.replaceChildren();
  cells.forEach((row, r) => row.forEach((color, c) => {
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = `tile ${color}`;
    tile.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}, ${color}`);
    tile.addEventListener('click', () => fill(r, c));
    grid.append(tile);
  }));
}

function fill(row, col) {
  if (!selectedColor || finished) {
    if (!selectedColor) message.textContent = 'Choose a color first.';
    return;
  }
  const target = cells[row][col];
  if (target === selectedColor) {
    message.textContent = 'Choose a different color to fill.';
    return;
  }
  const stack = [[row, col]];
  const visited = new Set();
  while (stack.length) {
    const [r, c] = stack.pop();
    const key = `${r},${c}`;
    if (r < 0 || r >= 6 || c < 0 || c >= 6 || visited.has(key) || cells[r][c] !== target) continue;
    visited.add(key);
    cells[r][c] = selectedColor;
    stack.push([r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]);
  }
  moves++;
  moveCount.textContent = moves;
  const uniform = cells.every(row => row.every(color => color === cells[0][0]));
  finished = uniform;
  message.textContent = uniform ? 'One color!' : 'Area filled. Choose your next color.';
  render();
}

colorButtons.forEach(button => button.addEventListener('click', () => {
  selectedColor = button.dataset.color;
  colorButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
  if (!finished) message.textContent = `Selected ${selectedColor}. Click a tile to fill.`;
}));

document.querySelector('#restart').addEventListener('click', () => {
  cells = startingPattern.map(row => [...row]);
  moves = 0;
  selectedColor = null;
  finished = false;
  moveCount.textContent = '0';
  message.textContent = 'Pick a color to begin.';
  colorButtons.forEach(button => button.setAttribute('aria-pressed', 'false'));
  render();
});

document.querySelector('#restart').click();
